      7: { items: ["الجدول فيه أعمدة، ولكل عمود اسم ونوع بيانات.", "INT يخزّن الأعداد الصحيحة وVARCHAR(255) يخزّن نصاً قصيراً.", "PRIMARY KEY تعني أن كل صف له id فريد.", "AUTO_INCREMENT يجعل MySQL يرقّم الصفوف الجديدة لك.", "SHOW TABLES تسرد الجداول، وDESCRIBE تعرض الأعمدة."] },
      8: { text: "جدول customers هذا هو المثال المشترك لقسم MySQL كله. وكل درس لاحق يستخدم الأعمدة الثلاثة نفسها، فلا تغيّرها." },
