      4: { text: "الترتيب تنازلياً" },
      5: { text: "أضف DESC بعد اسم العمود للترتيب في الاتجاه المعاكس، من Z إلى A للنصوص ومن الكبير إلى الصغير للأعداد. وASC تعني تصاعدياً وهي الافتراضية، فلا تحتاج إلى كتابتها إلا عندما تريد الوضوح. ويمكنك أيضاً الترتيب بأكثر من عمود، مثلاً ORDER BY address, name، الذي يرتّب حسب العنوان أولاً ويستخدم الاسم لكسر التعادل." },
      7: { text: "تأتي ORDER BY بعد WHERE في الاستعلام، فيمكنك الترشيح والترتيب في الجملة نفسها. فمثلاً SELECT * FROM customers WHERE address LIKE '%Street%' ORDER BY name تُرجع الصفوف المطابقة مرتبة أصلاً. والترتيب لا يغيّر الجدول، بل يغيّر فقط ترتيب الصفوف التي تحصل عليها." },
      8: { items: ["ORDER BY ترتّب الصفوف التي يُرجعها الاستعلام.", "الترتيب الافتراضي تصاعدي، من A إلى Z أو من الصغير إلى الكبير.", "DESC تعكس الترتيب إلى تنازلي.", "يمكنك الترتيب بأكثر من عمود.", "تأتي ORDER BY بعد WHERE في الاستعلام."] },
