      7: { text: "يمكنك ضبط أكثر من عمود في آن واحد، مثلاً SET name = 'James', address = 'Canyon 123'. ويمكنك أيضاً تحديث عدة صفوف بجملة واحدة باستخدام WHERE أوسع، مثل WHERE address LIKE '%Street%'. وينطبق التحذير نفسه كما في DELETE: فـ UPDATE دون WHERE يغيّر كل صف في الجدول، فاختبر WHERE باستخدام SELECT أولاً." },
      8: { items: ["UPDATE يغيّر القيم في الصفوف المطابقة لشرط WHERE.", "SET تسمّي الأعمدة وقيمها الجديدة.", "مرّر القيم الجديدة بعناصر %s النائبة في بايثون.", "نادِ commit لحفظ التغيير.", "UPDATE دون WHERE يغيّر كل صف، فاختبر WHERE أولاً."] },
      9: { text: "عندما يجب أن يتغير صف واحد فقط، استخدم شرطاً يطابق صفاً واحداً، مثل الاسم أو id، وتحقق من rowcount بعد ذلك." },
